/**
 * The schema assistant's first run on the user's own database: once, by
 * itself, on the operator's AI.
 *
 * An operator project may connect the visitor's database as `yours`
 * (`ADMINIUM_YOUR_DATABASE`). Its pages are generated by rules; this run then
 * asks the schema assistant (LLM-assist, the same path as `POST /llm/runs` and
 * `/execute`) for labels, relations, nav groups, template and dashboard pages,
 * with the visitor's notes about the database as data, and applies what it
 * proposes (confidence {@link AUTO_ACCEPT_CONFIDENCE} or more) through the
 * ordinary apply. The apply's before-image is kept in `llm.yoursAssist`, so the
 * owner can undo it later (`POST /llm/yours-assist/undo`), not only within a
 * toast's minute.
 *
 * It starts when the last of these becomes true, whichever it is:
 *
 *   - `yours` is ready (introspected and generated: `project/your-database-state.ts`);
 *   - the first-run wizard made the owner's account (`setup/service.ts`);
 *   - an operator AI key is set: `ADMINIUM_AI_BUILD_API_KEY`, or the
 *     compatible gateway's key and address.
 *
 * It runs once for the instance's life: an operator tally is claimed first
 * (`adminium_operator_tallies`, as the Designer's start prompt does). With no
 * key nothing is claimed, so a later boot with a key runs it. A run that could
 * not even be made (no snapshot, no model) gives the tally back; one the model
 * answered keeps it, whatever came of it: the operator paid for it.
 *
 * A run the operator's AI refused before it answered anything (a 429: the
 * server's build slots are full, or the operator's daily cap is reached) has
 * spent nothing, as the Designer's start prompt refused at the cap
 * (`designer/start-prompt.ts`). The tally is given back and the run waits
 * (`waiting`, with `until`; {@link waitFor}): the refusal's `Retry-After`, a
 * longer one (the daily cap) or too many in a row {@link YOURS_ASSIST_CAP_WAIT_MS}.
 * The time is kept in a tally ({@link YOURS_ASSIST_WAIT_TALLY}), so a server
 * restarted meanwhile starts it again at its next boot, at that time.
 *
 * No archive carries the tally (`archive/policy.ts`: the operator's tallies are
 * never set back by a file), but every archive carries the run's record
 * (`llm.yoursAssist`). So a store restored from one (an upgrade and restore,
 * then the owner reconnecting their database) knows from the record that the
 * run happened ({@link ranBefore}): the tally is taken again and nothing runs.
 *
 * It never makes tables: LLM-assist writes overrides and pages only, and no
 * table is ever created on `yours` (`connections/no-app-tables.ts`).
 */
import { isBootstrapRequired, operatorTalliesRepo, settingsRepo, type LlmRun, type MetaDb, type YoursAssistRecord } from '@adminium/meta';

import { selectAcceptedByConfidence, type ApplyService } from './apply-service.js';
import { YOURS_KEY } from '../connections/no-app-tables.js';
import { executeLlmRun, type ResolveRun } from '../jobs/llm-run.js';
import type { PromptService } from './prompt-service.js';
import type { RunService } from './run-service.js';
import type { YourDatabaseStatus } from '../project/your-database-state.js';
import { onSuperAdminCreated } from '../setup/service.js';

/** The tally that says the run has been taken. */
export const YOURS_ASSIST_TALLY = 'yours-assist';
/** The tally that holds when a run refused by the operator's AI starts again (ms since the epoch); none when nothing waits. */
export const YOURS_ASSIST_WAIT_TALLY = 'yours-assist-wait';

/** How long a run waits when the refusal did not say: the operator gateway's own `Retry-After` for full build slots. */
export const YOURS_ASSIST_RETRY_MS = 30_000;
/** The shortest wait: a `Retry-After: 0` is never a tight loop. */
export const YOURS_ASSIST_MIN_WAIT_MS = 5_000;
/** The longest `Retry-After` waited as it is. A longer one is the operator's daily cap (until midnight UTC). */
export const YOURS_ASSIST_MAX_SHORT_WAIT_MS = 5 * 60_000;
/** Short waits in a row before every later one is {@link YOURS_ASSIST_CAP_WAIT_MS}. */
export const YOURS_ASSIST_SHORT_TRIES = 10;
/** The long wait: the operator's cap, or a server busy for too long. The start prompt's (`START_PROMPT_RETRY_MS`). */
export const YOURS_ASSIST_CAP_WAIT_MS = 15 * 60_000;

/** The waits, for a test to shorten. */
export interface YoursAssistWaits {
  defaultMs: number;
  minMs: number;
  maxShortMs: number;
  shortTries: number;
  capMs: number;
}

const WAITS: YoursAssistWaits = {
  defaultMs: YOURS_ASSIST_RETRY_MS,
  minMs: YOURS_ASSIST_MIN_WAIT_MS,
  maxShortMs: YOURS_ASSIST_MAX_SHORT_WAIT_MS,
  shortTries: YOURS_ASSIST_SHORT_TRIES,
  capMs: YOURS_ASSIST_CAP_WAIT_MS,
};

/**
 * How long a refused run waits, and why: the refusal's `Retry-After` (or the default), at least the shortest wait;
 * the long wait for one past the short bound (`cap`) or once the short tries are spent (`busy`).
 */
export function waitFor(retryAfterMs: number | undefined, shortTriesSoFar: number, waits: YoursAssistWaits = WAITS): { ms: number; reason: 'busy' | 'cap'; short: boolean } {
  const asked = retryAfterMs ?? waits.defaultMs;
  if (asked > waits.maxShortMs) return { ms: waits.capMs, reason: 'cap', short: false };
  if (shortTriesSoFar >= waits.shortTries) return { ms: waits.capMs, reason: 'busy', short: false };
  return { ms: Math.max(waits.minMs, asked), reason: 'busy', short: true };
}

/**
 * A run the operator's AI refused before the model answered anything: failed on a rate limit (429), with no token
 * and no chunk received. Its `Retry-After`, when it gave one. Null for any other run.
 */
export function refusedBeforeAnswer(run: Pick<LlmRun, 'status' | 'tokensIn' | 'tokensOut' | 'chunksReceived' | 'validationErrors'>): { retryAfterMs: number | undefined } | null {
  if (run.status !== 'failed' || (run.tokensIn ?? 0) + (run.tokensOut ?? 0) > 0 || run.chunksReceived > 0) return null;
  const errors = Array.isArray(run.validationErrors) ? (run.validationErrors as unknown[]) : [];
  if (errors.length === 0) return null;
  let retryAfterMs: number | undefined;
  for (const error of errors) {
    if (typeof error !== 'object' || error === null) return null;
    const entry = error as { kind?: unknown; code?: unknown; retryAfterMs?: unknown };
    if (entry.kind !== 'provider' || entry.code !== 'rate_limit') return null;
    if (retryAfterMs === undefined && typeof entry.retryAfterMs === 'number' && Number.isFinite(entry.retryAfterMs)) retryAfterMs = entry.retryAfterMs;
  }
  return { retryAfterMs };
}

export { YOURS_KEY };

/** Suggestions applied without a person: this sure, or more. */
export const AUTO_ACCEPT_CONFIDENCE = 0.5;

/** What the run ended as, for the operator's `assist.finished` event (`waiting`: it has not ended, and nothing is told). */
export interface YoursAssistOutcome {
  state: 'applied' | 'failed' | 'waiting';
  runId: string | null;
  connectionId: string;
  counts: Record<string, number> | null;
  reason: string | null;
  /** Tokens the model was sent and gave back. */
  tokens: number;
}

export interface YoursAssistDeps {
  meta: MetaDb;
  /** The `yours` connection's id, or null when there is none (yet). */
  yoursConnectionId: () => Promise<string | null>;
  /** Cleaned notes from `ADMINIUM_YOUR_DATABASE`, or null. */
  notes: string | null;
  /** An operator AI key is set (`ADMINIUM_AI_BUILD_API_KEY`, or the compatible gateway's key and address). */
  operatorKey: boolean;
  status: YourDatabaseStatus;
  promptService: Pick<PromptService, 'createRunForConnection'>;
  runService: RunService;
  applyService: Pick<ApplyService, 'applyRun' | 'buildPlanForRun'>;
  /** The direct path's resolver (`llm/provider-resolver.ts`): the schema assistant's own, with the build key. */
  resolve: ResolveRun;
  /** Told once the run ends (operator event `assist.finished`). */
  onFinished?: ((outcome: YoursAssistOutcome) => void) | undefined;
  log?: ((message: string, data?: Record<string, unknown>) => void) | undefined;
  now?: () => number;
  /** The waits after a refusal; a test shortens them. */
  waits?: Partial<YoursAssistWaits> | undefined;
}

export type YoursAssistStart =
  | { started: false; reason: 'not-ready' | 'no-owner' | 'no-key' | 'no-connection' | 'taken' | 'running' | 'waiting' }
  | { started: true; done: Promise<YoursAssistOutcome> };

export interface YoursAssist {
  /** Start the run when everything it waits for is there. Safe to call any number of times. */
  maybeStart(): Promise<YoursAssistStart>;
  /** Listen for what it waits for (the database ready, an owner made), and check once now. */
  watch(): () => void;
  /** Stop a timer set for a refused run (server close). A later boot starts it again at its time. */
  stop(): void;
}

/** Whether the operator gave this server an AI key builds may run on. */
/** An `assist.finished` event as the operator receives it (`operator/events.ts`). */
export interface AssistFinishedEvent {
  runId: string;
  connectionId: string;
  status: 'applied' | 'partially_applied' | 'failed' | 'discarded';
  tokens: number;
  notes: boolean;
}

/**
 * The run service's end listener for the operator's `assist.finished`: one event per schema-assistant run that ends.
 * Not for the notes run's own runs (on `yours`, started by nobody): a refused try ends `failed` and is tried again, so
 * the notes run says once how it ended ({@link YoursAssistDeps.onFinished}), never each try.
 */
export function assistEndedReporter(deps: {
  projectKeyOf: (connectionId: string) => Promise<string | null>;
  assistFinished: (event: AssistFinishedEvent) => void;
}): (run: Pick<LlmRun, 'id' | 'connectionId' | 'status' | 'tokensIn' | 'tokensOut' | 'createdBy'>) => void {
  return (run) => {
    if (run.status !== 'applied' && run.status !== 'partially_applied' && run.status !== 'failed' && run.status !== 'discarded') return;
    const status = run.status;
    void deps
      .projectKeyOf(run.connectionId)
      .catch(() => null)
      .then((projectKey) => {
        const onYours = projectKey === YOURS_KEY;
        if (onYours && run.createdBy === null) return;
        deps.assistFinished({ runId: run.id, connectionId: run.connectionId, status, tokens: (run.tokensIn ?? 0) + (run.tokensOut ?? 0), notes: onYours });
      });
  };
}

/**
 * Whether a record says the run already happened: anything but none, a wait (refused before an answer) or a run
 * that could not be made (`no-model`). Both of those gave the tally back, so they may run.
 */
export function ranBefore(held: YoursAssistRecord | null): held is YoursAssistRecord {
  if (held === null || held.state === 'waiting') return false;
  return !(held.state === 'failed' && held.reason === 'no-model');
}

export function hasOperatorBuildKey(env: {
  ADMINIUM_AI_BUILD_API_KEY?: string | undefined;
  ADMINIUM_AI_COMPATIBLE_API_KEY?: string | undefined;
  ADMINIUM_AI_COMPATIBLE_BASE_URL?: string | undefined;
}): boolean {
  if ((env.ADMINIUM_AI_BUILD_API_KEY ?? '') !== '') return true;
  return (env.ADMINIUM_AI_COMPATIBLE_API_KEY ?? '') !== '' && (env.ADMINIUM_AI_COMPATIBLE_BASE_URL ?? '') !== '';
}

export function createYoursAssist(deps: YoursAssistDeps): YoursAssist {
  const now = deps.now ?? Date.now;
  const tallies = operatorTalliesRepo(deps.meta);
  const settings = settingsRepo(deps.meta);
  const log = deps.log ?? (() => undefined);
  const waits: YoursAssistWaits = { ...WAITS, ...deps.waits };
  let inFlight: Promise<YoursAssistOutcome> | null = null;
  let timer: NodeJS.Timeout | null = null;
  let stopped = false;
  /** Short waits in a row in this process: bounded, then every wait is the long one. */
  let shortTries = 0;

  /** Start again at `at`: the wait is over once the timer fires, whatever the clock says. */
  const schedule = (at: number): void => {
    if (stopped) return;
    if (timer !== null) clearTimeout(timer);
    timer = setTimeout(
      () => {
        timer = null;
        void (async () => {
          // The run that set this wait may still be closing.
          if (inFlight !== null) await inFlight.catch(() => undefined);
          await tallies.release(YOURS_ASSIST_WAIT_TALLY);
          await maybeStart();
        })().catch((error: unknown) => {
          log('yours-assist: could not start again', { error: error instanceof Error ? error.message : String(error) });
        });
      },
      Math.max(0, at - now()),
    );
    timer.unref();
  };

  const record = async (value: YoursAssistRecord): Promise<void> => {
    await settings.set('llm.yoursAssist', value, { at: value.at });
  };

  async function run(connectionId: string): Promise<YoursAssistOutcome> {
    const finish = async (outcome: YoursAssistOutcome, undo: unknown = null): Promise<YoursAssistOutcome> => {
      await record({ state: outcome.state, runId: outcome.runId, connectionId, at: now(), counts: outcome.counts, undo, reason: outcome.reason }).catch(() => undefined);
      try {
        deps.onFinished?.(outcome);
      } catch {
        // The event is the operator's; the run is done either way.
      }
      return outcome;
    };

    let runId: string;
    try {
      const created = await deps.promptService.createRunForConnection({
        connectionId,
        path: 'provider',
        sampling: null,
        createdBy: null,
        notes: deps.notes,
      });
      runId = created.run.id;
    } catch (error) {
      // Nothing was sent: the next boot (or a model set later) may run it.
      await tallies.release(YOURS_ASSIST_TALLY).catch(() => undefined);
      log('yours-assist: could not make the run', { error: error instanceof Error ? error.message : String(error) });
      return finish({ state: 'failed', runId: null, connectionId, counts: null, reason: 'no-model', tokens: 0 });
    }
    await record({ state: 'running', runId, connectionId, at: now(), counts: null, undo: null, reason: null });

    const controller = new AbortController();
    await executeLlmRun(
      { runId },
      {
        jobId: `yours-assist:${runId}`,
        kind: 'yours-assist',
        attempt: 1,
        maxAttempts: 1,
        signal: controller.signal,
        progress: () => undefined,
        log: (message, data) => {
          log(message, data);
        },
      },
      { runService: deps.runService, resolve: deps.resolve, now },
    );
    const done = await deps.runService.getRun(runId);
    const tokens = (done?.tokensIn ?? 0) + (done?.tokensOut ?? 0);
    const refused = done === null ? null : refusedBeforeAnswer(done);
    if (refused !== null) {
      // Refused before the model answered anything: nothing was spent. The tally goes back, and the run waits.
      const wait = waitFor(refused.retryAfterMs, shortTries, waits);
      shortTries = wait.short ? shortTries + 1 : 0;
      const until = now() + wait.ms;
      await tallies.release(YOURS_ASSIST_WAIT_TALLY);
      await tallies.raise(YOURS_ASSIST_WAIT_TALLY, until);
      await tallies.release(YOURS_ASSIST_TALLY);
      await record({ state: 'waiting', runId, connectionId, at: now(), counts: null, undo: null, reason: wait.reason, until }).catch(() => undefined);
      log('yours-assist: the operator AI is busy; it starts again later', { runId, reason: wait.reason, until, retryAfterMs: refused.retryAfterMs ?? null });
      schedule(until);
      return { state: 'waiting', runId, connectionId, counts: null, reason: wait.reason, tokens: 0 };
    }
    if (done === null || done.status !== 'validated') {
      return finish({ state: 'failed', runId, connectionId, counts: null, reason: done?.status === 'failed' ? 'provider' : 'invalid', tokens });
    }
    try {
      const { diff } = await deps.applyService.buildPlanForRun(done, []);
      const accepted = selectAcceptedByConfidence(diff, AUTO_ACCEPT_CONFIDENCE);
      const applied = await deps.applyService.applyRun(runId, accepted, { appliedBy: null });
      const counts: Record<string, number> = { overrides: applied.counts.overrides, pages: applied.counts.pages, navGroupUpdates: applied.counts.navGroupUpdates };
      log('yours-assist: applied', { runId, ...counts });
      return finish({ state: 'applied', runId, connectionId, counts, reason: null, tokens }, applied.undo);
    } catch (error) {
      log('yours-assist: could not apply', { runId, error: error instanceof Error ? error.message : String(error) });
      return finish({ state: 'failed', runId, connectionId, counts: null, reason: 'apply', tokens });
    }
  }

  async function maybeStart(): Promise<YoursAssistStart> {
    if (inFlight !== null) return { started: false, reason: 'running' };
    if (deps.status.current()?.state !== 'ready') return { started: false, reason: 'not-ready' };
    if (await isBootstrapRequired(deps.meta)) return { started: false, reason: 'no-owner' };
    if (!deps.operatorKey) return { started: false, reason: 'no-key' };
    const connectionId = await deps.yoursConnectionId();
    if (connectionId === null) return { started: false, reason: 'no-connection' };
    const waiting = await tallies.get(YOURS_ASSIST_WAIT_TALLY);
    if (waiting !== null) {
      if (waiting.amount > now()) {
        // Refused earlier (this process, or one before a restart): it starts again at its time, not before.
        if (timer === null) schedule(waiting.amount);
        return { started: false, reason: 'waiting' };
      }
      await tallies.release(YOURS_ASSIST_WAIT_TALLY);
    }
    const before = await settings.get('llm.yoursAssist');
    if (ranBefore(before)) {
      // It ran. Restored from an archive, the record came back and the tally did not: take it again.
      if (await tallies.claim(YOURS_ASSIST_TALLY, now())) log('yours-assist: ran before this store was restored; not run again', { runId: before.runId, state: before.state });
      // A run this process never finished (a restart mid-run, or an archive made mid-run) is said to have stopped.
      if (before.state === 'running') await record({ ...before, state: 'interrupted', at: now() }).catch(() => undefined);
      return { started: false, reason: 'taken' };
    }
    // Taken with no record yet: a run starting elsewhere.
    if (!(await tallies.claim(YOURS_ASSIST_TALLY, now()))) return { started: false, reason: 'taken' };
    const done = run(connectionId)
      .catch(async (error: unknown) => {
        log('yours-assist: stopped', { error: error instanceof Error ? error.message : String(error) });
        return { state: 'failed' as const, runId: null, connectionId, counts: null, reason: 'apply', tokens: 0 };
      })
      .finally(() => {
        inFlight = null;
      });
    inFlight = done;
    return { started: true, done };
  }

  function stop(): void {
    stopped = true;
    if (timer !== null) clearTimeout(timer);
    timer = null;
  }

  return {
    maybeStart,
    watch() {
      const check = (): void => {
        void maybeStart().catch(() => undefined);
      };
      const offStatus = deps.status.onChange((state) => {
        if (state.state === 'ready') check();
      });
      const offOwner = onSuperAdminCreated(check);
      check();
      return () => {
        offStatus();
        offOwner();
        stop();
      };
    },
    stop,
  };
}

/** Undo the run's apply, from its kept before-image. False when there is nothing to undo. */
export async function undoYoursAssist(meta: MetaDb, applyService: Pick<ApplyService, 'undoApply'>, now: () => number = Date.now): Promise<YoursAssistRecord | null> {
  const settings = settingsRepo(meta);
  const held = await settings.get('llm.yoursAssist');
  if (held === null || held.state !== 'applied' || held.undo === null) return null;
  await applyService.undoApply(held.undo as Parameters<ApplyService['undoApply']>[0]);
  const next: YoursAssistRecord = { ...held, state: 'undone', undo: null, at: now() };
  await settings.set('llm.yoursAssist', next, { at: next.at });
  return next;
}
